UPDATE TB_TRMA_TOUR_LIST
TOUR_NM_EN = IF(NULLIF(TOUR_NM_EN, '') IS NULL, #{tourNmEn}, TOUR_NM_EN), TOUR_NM_JA = IF(NULLIF(TOUR_NM_JA, '') IS NULL, #{tourNmJa}, TOUR_NM_JA), TOUR_CONTENT_EN = IF(NULLIF(TOUR_CONTENT_EN, '') IS NULL, #{overviewEn}, TOUR_CONTENT_EN), TOUR_CONTENT_JA = IF(NULLIF(TOUR_CONTENT_JA, '') IS NULL, #{overviewJa}, TOUR_CONTENT_JA), ROAD_ADDR_EN = IF(NULLIF(ROAD_ADDR_EN, '') IS NULL OR ROAD_ADDR_EN REGEXP '[가-힣]', #{roadAddrEn}, ROAD_ADDR_EN), ROAD_ADDR_JA = IF(NULLIF(ROAD_ADDR_JA, '') IS NULL OR ROAD_ADDR_JA REGEXP '[가-힣]', #{roadAddrJa}, ROAD_ADDR_JA), DETAIL_ADDR_EN = IF(NULLIF(DETAIL_ADDR_EN, '') IS NULL OR DETAIL_ADDR_EN REGEXP '[가-힣]', #{detailAddrEn}, DETAIL_ADDR_EN), DETAIL_ADDR_JA = IF(NULLIF(DETAIL_ADDR_JA, '') IS NULL OR DETAIL_ADDR_JA REGEXP '[가-힣]', #{detailAddrJa}, DETAIL_ADDR_JA),
WHERE TOUR_ID = #{tourId}

UPDATE TB_TRMA_MOIM_REVIEW
REVIEW_TITLE_${lang} = #{title}, REVIEW_CONTENT_${lang} = #{content},
WHERE REVIEW_ID = #{reviewId}

UPDATE TB_TRMA_MOIM_REVIEW
REVIEW_TITLE_EN = #{reviewTitleEn}, REVIEW_TITLE_JA = #{reviewTitleJa}, REVIEW_CONTENT_EN = #{reviewContentEn}, REVIEW_CONTENT_JA = #{reviewContentJa},
WHERE REVIEW_ID = #{reviewId}

