UPDATE TB_TRMA_TOUR_LIST
SET DUP_YN = 'Y'
WHERE TOUR_ID = #{tourId}
    AND #{roadAddr} != ''
    AND EXISTS (
        SELECT 1 FROM TB_TRMA_TOUR_LIST b2
        WHERE b2.ROAD_ADDR = #{roadAddr}
            AND b2.USE_YN = 'Y'
            AND b2.TOUR_ID != #{tourId}
    )
